package events

// subKey identifies the set of subscriptions belonging to one device's view
// of one document: change commits wake every device set under the document,
// a permission revoke closes only the one (document, device) set.
type subKey struct {
	document string
	device   string
}

// subscription is one in-memory, push-only observer of the change log.
//
// It belongs to a (document, device) pair — the device is the one owning the
// session that opened the connection. It receives one coalesceable signal per
// change-producing commit (PostChanges, ReplayChanges, MergeChange and
// RestoreSnapshot all signal through the same hook long polling uses). The
// permission service closes the separate one-shot revoked channel when it
// revokes the keyed pair; closing is sticky, so a later grant never reopens
// it.
//
// A subscription leaves no durable trace: nothing is written, a disconnect
// simply unregisters, and a stop broadcasts one final wakeup. Pushing never
// allocates a cursor or inserts a change row.
type subscription struct {
	// wakes receives one value on every change commit for the keyed document.
	// It is buffered (and signals coalesce) so a commit is never dropped or
	// blocked while the consumer is reading the log.
	wakes chan struct{}
	// revoked is closed once, the first time permission for the keyed pair is
	// revoked while this subscription is live. Closing is sticky.
	revoked       chan struct{}
	revokedClosed bool
}

// AddSubscription registers an in-memory subscription for documentID as seen
// by deviceID. It returns:
//
//   - wakes: signaled (coalesceably) after every change commit on documentID;
//   - revoked: closed once if/when permission for (documentID, deviceID) is
//     revoked while the subscription is live;
//   - unregister: idempotent removal; a client disconnect, a permission close
//     and a service stop may all race to call it.
//
// If the service is already stopping the wake channel is signaled immediately
// and unregister is a no-op, so a late subscriber parks on nothing.
func (s *Service) AddSubscription(documentID, deviceID string) (wakes <-chan struct{}, revoked <-chan struct{}, unregister func()) {
	ch := make(chan struct{}, 1)
	sub := &subscription{wakes: ch, revoked: make(chan struct{})}
	key := subKey{document: documentID, device: deviceID}

	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		close(ch)
		return ch, sub.revoked, func() {}
	}
	s.subWG.Add(1)
	s.nextSub++
	id := s.nextSub
	set := s.subs[key]
	if set == nil {
		set = make(map[uint64]*subscription)
		s.subs[key] = set
	}
	set[id] = sub
	remove := func() {
		s.mu.Lock()
		if set, ok := s.subs[key]; ok {
			if _, ok := set[id]; ok {
				delete(set, id)
				if len(set) == 0 {
					delete(s.subs, key)
				}
				s.mu.Unlock()
				s.subWG.Done()
				return
			}
		}
		s.mu.Unlock()
	}
	return ch, sub.revoked, remove
}

// signalSubscribers wakes every subscription open on documentID. It is called
// only after a change-bearing transaction has committed, so when a woken
// subscription re-reads the log the new rows are visible.
func (s *Service) signalSubscribers(documentID string) {
	s.mu.Lock()
	var targets []chan struct{}
	for key, set := range s.subs {
		if key.document != documentID {
			continue
		}
		for _, sub := range set {
			targets = append(targets, sub.wakes)
		}
	}
	s.mu.Unlock()

	for _, ch := range targets {
		select {
		case ch <- struct{}{}:
		default:
			// A signal the consumer has not drained yet is already pending; the
			// pending wake covers this commit too because the consumer re-reads
			// from its last observed cursor.
		}
	}
}

// SignalRevoked closes the one-shot revoked channel of every subscription open
// on (documentID, deviceID), so the connection layer ends those subscriptions
// with the permission-closed code even if a grant races in afterward. Other
// devices' and other documents' subscriptions are untouched. It is the
// permission service's revoke hook for the change event service.
func (s *Service) SignalRevoked(documentID, deviceID string) {
	s.mu.Lock()
	set := s.subs[subKey{document: documentID, device: deviceID}]
	targets := make([]*subscription, 0, len(set))
	for _, sub := range set {
		if !sub.revokedClosed {
			sub.revokedClosed = true
			targets = append(targets, sub)
		}
	}
	s.mu.Unlock()

	for _, sub := range targets {
		close(sub.revoked)
	}
}

// SignalDeviceDeregistered ends every live subscription belonging to
// deviceID across every document, after the device's deregistration
// transaction committed: the session backing such a connection is already
// hard-deleted, so the connection closes immediately with the same
// permission-closed code a revoke uses — stickily, nothing can reopen it.
// Other devices' subscriptions are untouched.
func (s *Service) SignalDeviceDeregistered(deviceID string) {
	s.mu.Lock()
	var targets []*subscription
	for key, set := range s.subs {
		if key.device != deviceID {
			continue
		}
		for _, sub := range set {
			if !sub.revokedClosed {
				sub.revokedClosed = true
				targets = append(targets, sub)
			}
		}
	}
	s.mu.Unlock()

	for _, sub := range targets {
		close(sub.revoked)
	}
}

// Closing reports whether the service has begun stopping. A woken subscription
// uses it to distinguish a termination signal from a commit.
func (s *Service) Closing() bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.closed
}

// interruptWaits wakes every parked long poll without closing the database, so
// an orderly shutdown drains waiting connections immediately (they answer 503)
// instead of holding shutdown hostage until their wait deadline. Committed
// state is untouched. Live subscriptions get one last wakeup as well; the
// connection layer re-checks the closed flag and finishes with a going-away
// close.
func (s *Service) InterruptWaits() {
	s.mu.Lock()
	s.closed = true
	waits := s.waits
	s.waits = map[string]map[uint64]chan struct{}{}
	// Snapshot the live subscription channels without reaping the registry:
	// unregister remains valid while handlers drain, so the WaitGroup in
	// shutdown balances. New AddSubscription calls fail fast on closed.
	var subChans []chan struct{}
	for _, set := range s.subs {
		for _, sub := range set {
			subChans = append(subChans, sub.wakes)
		}
	}
	s.mu.Unlock()
	for _, set := range waits {
		for _, ch := range set {
			close(ch)
		}
	}
	for _, ch := range subChans {
		select {
		case ch <- struct{}{}:
		default:
		}
	}
}

// waitSubscriptions blocks until every subscription handler has unregistered.
func (s *Service) WaitDrained() {
	s.subWG.Wait()
}

package events

import (
	"context"
	"database/sql"
	"time"
)

// DocumentExists reports whether documentID is a known document rather than an
// empty namespace: it has any online change row, or a compaction boundary from
// a log that was (fully or partially) trimmed.
func (s *Service) DocumentExists(documentID string) (bool, error) {
	var known bool
	if err := s.db.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM changes WHERE document_id = ?)
		 OR EXISTS(SELECT 1 FROM change_boundaries WHERE document_id = ?)`,
		documentID, documentID,
	).Scan(&known); err != nil {
		return false, err
	}
	return known, nil
}

// ListChanges returns at most limit changes for documentID whose cursor is
// greater than after and still online, in cursor order, together with the
// cursor to pass as the next after value. An unknown document yields an empty
// list and cursor 0; a known document with no rows past after yields
// nextCursor == max(after, boundary), so a caller positioned inside the
// trimmed range resumes from the compaction boundary.
func (s *Service) ListChanges(documentID string, after, limit int64) ([]ListedChange, int64, error) {
	rows, err := s.db.Query(
		`SELECT id, device_id, payload, cursor FROM changes
		 WHERE document_id = ? AND cursor > ?
		 ORDER BY cursor ASC
		 LIMIT ?`,
		documentID, after, limit,
	)
	if err != nil {
		return nil, 0, err
	}
	defer func() { _ = rows.Close() }()

	out := make([]ListedChange, 0)
	var maxCursor int64 = after
	for rows.Next() {
		var c ListedChange
		if err := rows.Scan(&c.ID, &c.DeviceID, &c.Payload, &c.Cursor); err != nil {
			return nil, 0, err
		}
		out = append(out, c)
		maxCursor = c.Cursor
	}
	if err := rows.Err(); err != nil {
		return nil, 0, err
	}

	// Distinguish an unknown document from a known one with nothing new:
	// unknown documents must report nextCursor 0, while a known document
	// reports the greater of after and the compaction boundary.
	if len(out) == 0 {
		known, err := s.DocumentExists(documentID)
		if err != nil {
			return nil, 0, err
		}
		if !known {
			return out, 0, nil
		}
		boundary, err := boundaryOfTx(s.db, documentID)
		if err != nil {
			return nil, 0, err
		}
		if boundary > maxCursor {
			maxCursor = boundary
		}
	}
	return out, maxCursor, nil
}

// ExportChanges returns every change of documentID whose cursor lies in the
// closed interval [from, to] and is still in the online log, in ascending
// cursor order. When to is nil no upper bound is applied. An unknown document,
// or a range without any online change — including one that lies entirely
// inside the trimmed region — yields an empty list and no error: the export is
// a read that misses like any other. The (document_id, cursor) unique index
// guarantees a cursor appears at most once.
//
// The single SELECT runs as one SQLite statement over the serialized
// connection, so a batch committed concurrently is observed either with all of
// its rows or not at all — never half of it. The read starts no transaction,
// writes nothing and notifies no waiters, so it cannot move a cursor, produce
// a change record or wake a parked poll. Each returned row is the same record
// the paged read emits at that cursor.
func (s *Service) ExportChanges(documentID string, from int64, to *int64) ([]ListedChange, error) {
	var (
		rows *sql.Rows
		err  error
	)
	if to == nil {
		rows, err = s.db.Query(
			`SELECT id, device_id, payload, cursor FROM changes
			 WHERE document_id = ? AND cursor >= ?
			 ORDER BY cursor ASC`,
			documentID, from,
		)
	} else {
		rows, err = s.db.Query(
			`SELECT id, device_id, payload, cursor FROM changes
			 WHERE document_id = ? AND cursor >= ? AND cursor <= ?
			 ORDER BY cursor ASC`,
			documentID, from, *to,
		)
	}
	if err != nil {
		return nil, err
	}
	defer func() { _ = rows.Close() }()

	out := make([]ListedChange, 0)
	for rows.Next() {
		var c ListedChange
		if err := rows.Scan(&c.ID, &c.DeviceID, &c.Payload, &c.Cursor); err != nil {
			return nil, err
		}
		out = append(out, c)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return out, nil
}

// WaitForChanges blocks until documentID has a change with cursor greater than
// after, a change is committed while waiting, wait elapses, ctx is canceled
// (the client disconnected) or the service stops. It then returns the current
// page of up to limit changes exactly as ListChanges would, with timedOut=true
// only when the wait deadline expired with no new rows.
//
// Registration precedes the first query: a commit landing between the read and
// the park still notifies a registered channel, so no change is missed.
//
// An unknown document is never parked on: it returns immediately with an empty
// list and nextCursor 0, timedOut=false. Data already past after is likewise
// returned immediately. wait <= 0 is an immediately expired deadline.
func (s *Service) WaitForChanges(ctx context.Context, documentID string, after, limit int64, wait time.Duration) (changes []ListedChange, nextCursor int64, timedOut bool, err error) {
	ch, remove := s.registerWait(documentID)
	defer remove()

	changes, nextCursor, err = s.ListChanges(documentID, after, limit)
	if err != nil || len(changes) > 0 {
		return changes, nextCursor, false, err
	}

	// Empty page: distinguish an unknown document (immediate empty/0, never
	// parked on) from a known document caught up to after.
	known, err := s.DocumentExists(documentID)
	if err != nil || !known {
		return changes, 0, false, err
	}

	// Known document, nothing new: a zero wait is an immediately expired
	// deadline; ListChanges already echoes nextCursor == after.
	if wait <= 0 {
		return changes, nextCursor, true, nil
	}

	timer := time.NewTimer(wait)
	defer timer.Stop()

	select {
	case <-ch:
		// Woken by a committed change or by InterruptWaits.
		s.mu.Lock()
		closing := s.closed
		s.mu.Unlock()
		if closing {
			return nil, 0, false, ErrStoreClosing
		}
		changes, nextCursor, err = s.ListChanges(documentID, after, limit)
		return changes, nextCursor, len(changes) == 0, err
	case <-timer.C:
		// Timeout with no new rows: echo the caller's cursor without
		// advancing it. The document was known above, so ListChanges returns
		// nextCursor == after for an empty page.
		changes, nextCursor, err = s.ListChanges(documentID, after, limit)
		return changes, nextCursor, len(changes) == 0, err
	case <-ctx.Done():
		return nil, 0, false, ctx.Err()
	}
}

// registerWait parks a channel for documentID and returns it together with a
// removal function. The channel is closed on the next committed change to the
// document, or when the service stops.
func (s *Service) registerWait(documentID string) (ch chan struct{}, remove func()) {
	ch = make(chan struct{}, 1)

	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		// Shutdown beat the registration: signal immediately so the caller does
		// not park on a channel nobody will close.
		close(ch)
		return ch, func() {}
	}
	s.nextWait++
	id := s.nextWait
	set := s.waits[documentID]
	if set == nil {
		set = make(map[uint64]chan struct{})
		s.waits[documentID] = set
	}
	set[id] = ch
	return ch, func() {
		s.mu.Lock()
		if set, ok := s.waits[documentID]; ok {
			delete(set, id)
			if len(set) == 0 {
				delete(s.waits, documentID)
			}
		}
		s.mu.Unlock()
	}
}

// notifyWaiters signals every long poll parked on documentID and every
// subscription open on it. It is called only after a change-bearing
// transaction has committed, so parked readers observe the new rows when they
// re-query and pushed frames describe committed changes.
func (s *Service) notifyWaiters(documentID string) {
	s.mu.Lock()
	set := s.waits[documentID]
	delete(s.waits, documentID)
	s.mu.Unlock()
	for _, ch := range set {
		close(ch)
	}
	s.signalSubscribers(documentID)
}

package server

import (
	"errors"
	"net/http"
	"net/url"
	"strings"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/events"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// changeExportResponse is the export body with the top-level key order fixed
// to changes then count. Changes is always a non-nil slice so an empty
// export serializes as [] rather than null. Each element is an
// events.ListedChange, whose key order is id, deviceId, payload, cursor — the
// same record the paged read emits.
type changeExportResponse struct {
	Changes []events.ListedChange `json:"changes"`
	Count   int                   `json:"count"`
}

// exportRequested reports whether the query carries the export's from/to
// parameters. A present key counts even with an empty value (?from= is the
// export with the default bound), matching the document-level collection.
func exportRequested(q url.Values) bool {
	if _, ok := q["from"]; ok {
		return true
	}
	_, ok := q["to"]
	return ok
}

// parseExportInterval parses the shared from/to export parameters, writing
// the documented 400 on an illegal value. from defaults to 0; a nil to means
// the interval has no upper bound; to below from is rejected. It is shared by
// the document-scoped and session-scoped exports so their query semantics
// cannot drift apart.
func parseExportInterval(w http.ResponseWriter, q url.Values) (from int64, to *int64, ok bool) {
	from = 0
	if raw := q.Get("from"); raw != "" {
		v, valid := parseCursorPath(raw)
		if !valid {
			writeError(w, http.StatusBadRequest, "from must be a non-negative integer")
			return 0, nil, false
		}
		from = v
	}

	if raw := q.Get("to"); raw != "" {
		v, valid := parseCursorPath(raw)
		if !valid {
			writeError(w, http.StatusBadRequest, "to must be a non-negative integer")
			return 0, nil, false
		}
		to = &v
	}
	if to != nil && *to < from {
		writeError(w, http.StatusBadRequest, "to must not be less than from")
		return 0, nil, false
	}
	return from, to, true
}

// writeChangeExport renders an export result in the shared response shape: a
// single compact JSON line with the changes,count key order, an empty export
// serializing as [] with count 0.
func writeChangeExport(w http.ResponseWriter, rows []events.ListedChange) {
	if rows == nil {
		rows = make([]events.ListedChange, 0)
	}
	writeJSON(w, http.StatusOK, changeExportResponse{Changes: rows, Count: len(rows)})
}

// handleExportChanges is the read-only batch export over a document's change
// collection:
//
//	GET /v1/documents/{documentID}/changes?from=0&to=N
//
// from defaults to 0; to absent means no upper bound. Only changes whose
// cursor is in the closed [from, to] interval and still in the online log are
// returned, in ascending cursor order, at most one entry per cursor. An
// unknown document or a range without any online change — including one that
// lies entirely inside the trimmed region — is a successful 200 with an empty
// list and count 0, not an error. Changes compacted out of the online log
// never appear. The handler writes nothing: it creates no change, moves no
// cursor, records no change and notifies the push channels.
func handleExportChanges(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	from, to, ok := parseExportInterval(w, r.URL.Query())
	if !ok {
		return
	}

	rows, err := s.ExportChanges(documentID, from, to)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to export changes")
		return
	}
	writeChangeExport(w, rows)
}

// handleSessionExportChanges is the session-scoped view of the change-log
// batch export, sharing the session change read's exact collection path:
//
//	GET /v1/sessions/{sessionId}/documents/{documentId}/changes?from=0&to=N
//
// The interval semantics and the response body are identical to the
// document-level export; around them sit the session view's checks in their
// fixed order — request shape and parameters (400), session existence (404),
// the session device's document permission (403) — so a rejected export
// exposes no change content and writes nothing.
func handleSessionExportChanges(s *app.App, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
	documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty

	// Malformed interval parameters are a request-shape error (400) checked
	// before the resource lookup (404), matching the paged read's ordering.
	from, to, ok := parseExportInterval(w, r.URL.Query())
	if !ok {
		return
	}

	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}

	authorized, err := s.DocumentAuthorized(documentID, deviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to look up permission")
		return
	}
	if !authorized {
		writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		return
	}

	rows, err := s.ExportChanges(documentID, from, to)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to export changes")
		return
	}
	writeChangeExport(w, rows)
}

// malformedChangeExportPath reports whether p targets the change-log
// collection's export shape but is not the collection's exact location
// (/v1/documents/{documentID}/changes): a trailing slash (an empty trailing
// segment) or extra path segments past the collection. The paged read and
// this export share that exact collection path; its terminal subresources
// (poll, compact, subscribe under the session family) have their own keyword
// guards, so only a genuinely unrecognized suffix reaches this check.
// ServeMux would answer it with a redirect or a plain-text 404/405; the
// change surface promises a JSON error and never a redirect. Empty segments
// are already rejected by the guard itself. The keyword is matched only past
// the documentID position, so a document literally named "changes" keeps its
// ordinary routes.
func malformedChangeExportPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/documents/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	for i, seg := range segs {
		if seg != "changes" || i == 0 {
			continue
		}
		// Keyword position reached. The collection is exactly
		// {documentID}/changes; the poll and compact subresources are their own
		// endpoints and keep their own guards. Anything else (a trailing slash,
		// an unrecognized extra segment) is a malformed 400.
		if i == 1 {
			collection := len(segs) == 2 && segs[0] != ""
			knownSubresource := len(segs) >= 3 && (segs[2] == "poll" || segs[2] == "compact")
			return !(collection || knownSubresource)
		}
		return false
	}
	return false
}

// malformedSessionChangesPath reports whether p targets the session-scoped
// change collection's shape but is not the collection's exact location
// (/v1/sessions/{sessionId}/documents/{documentId}/changes): extra path
// segments past the collection. The paged read and the interval export share
// that exact collection path; the subscribe subresource has its own endpoint
// and keyword guard, so only a genuinely unrecognized suffix reaches this
// check. ServeMux would answer it with a plain-text 404; the change surface
// promises a JSON 400 and never a redirect. Empty segments (doubled slashes,
// a trailing slash) are already rejected by the guard itself.
//
// "changes" is treated as the collection keyword only in the fourth segment,
// right after the document identifier; a session or document identifier
// literally named "changes" occupies an identifier position and keeps its
// ordinary routes.
func malformedSessionChangesPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/sessions/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	// The CRDT namespace ("crdt" immediately past the document identifier)
	// has its own guard; "changes" there is an ordinary identifier, not this
	// collection's keyword.
	if len(segs) >= 4 && segs[1] == "documents" && segs[3] == "crdt" {
		return false
	}
	if len(segs) < 4 || segs[1] != "documents" || segs[3] != "changes" {
		return false
	}
	// Keyword position reached. The collection is exactly
	// {sessionId}/documents/{documentId}/changes; the subscribe subresource
	// adds one trailing "subscribe" segment and keeps its own guard; the long
	// poll adds one trailing "poll" segment and keeps its own guard; the
	// offline replay adds one trailing "replay" segment and keeps its own
	// guard. Anything else past the keyword is a malformed 400.
	collection := len(segs) == 4 && segs[0] != "" && segs[2] != ""
	subscribe := len(segs) == 5 && segs[4] == "subscribe"
	poll := len(segs) == 5 && segs[4] == "poll"
	replay := len(segs) == 5 && segs[4] == "replay"
	return !(collection || subscribe || poll || replay)
}

// malformedSessionPollPath reports whether p targets the session-scoped
// long-poll endpoint but is not at its exact location
// (/v1/sessions/{sessionId}/documents/{documentId}/changes/poll): a missing
// "documents"/"changes" segment, an extra segment, or a "poll" segment in a
// position short of the registered shape. ServeMux would answer those with a
// plain-text 404 (or a redirect for an empty segment); every failure of this
// endpoint must be a JSON 400 instead. Empty segments are already rejected by
// the guard itself.
//
// "poll" is treated as the endpoint keyword only in its terminal segment
// position (the fifth segment, index 4); a session or document identifier
// literally named "poll" occupies an identifier position (index 0 or 2) and is
// therefore left to the ordinary changes routes like any other id.
func malformedSessionPollPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/sessions/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	// The CRDT namespace ("crdt" immediately past the document identifier)
	// has its own guard; "poll" there is an ordinary identifier, not the
	// changes-poll keyword.
	if len(segs) >= 4 && segs[1] == "documents" && segs[3] == "crdt" {
		return false
	}
	for i, seg := range segs {
		if seg != "poll" {
			continue
		}
		// Identifier positions: sessionId (0) and documentId (2). A value of
		// "poll" there is an ordinary identifier, not the endpoint word.
		if i == 0 || i == 2 {
			continue
		}
		// Endpoint keyword position: the fifth segment must be exactly "poll"
		// with the documents/changes scaffolding around it, and no segment may
		// follow. Any other occurrence is a malformed path.
		if i == 4 && len(segs) == 5 &&
			segs[0] != "" &&
			segs[1] == "documents" &&
			segs[2] != "" &&
			segs[3] == "changes" {
			return false
		}
		return true
	}
	return false
}

// malformedSessionReplayPath reports whether p targets the session-scoped
// offline replay endpoint but is not at its exact location
// (/v1/sessions/{sessionId}/documents/{documentId}/changes/replay): a missing
// "documents"/"changes" segment, an extra segment, or a "replay" segment in a
// position short of the registered shape. ServeMux would answer those with a
// plain-text 404 (or a redirect for an empty segment); every failure of this
// endpoint must be a JSON 400 instead. Empty segments are already rejected by
// the guard itself.
//
// "replay" is treated as the endpoint keyword only in its terminal segment
// position (the fifth segment, index 4); a session or document identifier
// literally named "replay" occupies an identifier position (index 0 or 2) and
// is therefore left to the ordinary changes routes like any other id.
func malformedSessionReplayPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/sessions/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	// The CRDT namespace ("crdt" immediately past the document identifier)
	// has its own guard; "replay" there is an ordinary identifier, not the
	// changes-replay keyword.
	if len(segs) >= 4 && segs[1] == "documents" && segs[3] == "crdt" {
		return false
	}
	for i, seg := range segs {
		if seg != "replay" {
			continue
		}
		// Identifier positions: sessionId (0) and documentId (2). A value of
		// "replay" there is an ordinary identifier, not the endpoint word.
		if i == 0 || i == 2 {
			continue
		}
		// Endpoint keyword position: the fifth segment must be exactly
		// "replay" with the documents/changes scaffolding around it, and no
		// segment may follow. Any other occurrence is a malformed path.
		if i == 4 && len(segs) == 5 &&
			segs[0] != "" &&
			segs[1] == "documents" &&
			segs[2] != "" &&
			segs[3] == "changes" {
			return false
		}
		return true
	}
	return false
}

