141	func TestSessionPostChangesHTTPConflict(t *testing.T) {
142		h, s := newTestHandler(t)
143		createSessionViaHTTP(t, h, "dev", "sess")
144	
145		w, _ := postSessionChanges(t, h, "sess", "doc1", `{"changes":[{"id":"x","payload":{"k":1}}]}`)
146		if w.Code != http.StatusOK {
147			t.Fatal(w.Body.String())
148		}
149	
150		// Same id, different payload: 409 naming the conflicting id; the batch's
151		// other (valid, new) element is not written either.
152		w, body := postSessionChanges(t, h, "sess", "doc1", `{"changes":[
153			{"id":"fresh","payload":{"n":1}},
154			{"id":"x","payload":{"k":2}}
155		]}`)
156		if w.Code != http.StatusConflict {
157			t.Fatalf("payload conflict status = %d body = %s", w.Code, w.Body.String())
158		}
159		if ct := w.Header().Get("Content-Type"); ct != "application/json" {
160			t.Fatalf("conflict content type = %q", ct)
161		}
162		if body["error"] == nil || body["conflictId"] != "x" {
163			t.Fatalf("conflict body = %s", w.Body.String())
164		}
165	
166		// Same id and payload but a different source device is a conflict too:
167		// only the session device AND the decoded payload matching is idempotent.
168		createSessionViaHTTP(t, h, "dev-2", "sess-2")
169		w, body = postSessionChanges(t, h, "sess-2", "doc1", `{"changes":[{"id":"x","payload":{"k":1}}]}`)
170		if w.Code != http.StatusConflict || body["conflictId"] != "x" {
171			t.Fatalf("device conflict = %d %s", w.Code, w.Body.String())
172		}
173	
174		// Both conflicts left the log untouched: no half batch, cursor unmoved.
175		rows, next, err := s.ListChanges("doc1", 0, 100)
176		if err != nil {
177			t.Fatal(err)
178		}
179		if len(rows) != 1 || rows[0].ID != "x" || next != 1 {
180			t.Fatalf("conflict leaked writes: rows = %v next = %d", rows, next)
181		}
182	}
