609	
610	// An extra deviceId field in the body is ignored: the calling device is
611	// always the session's owning device, never a body field.
612	func TestSessionPostChangesHTTPExtraDeviceFieldIgnored(t *testing.T) {
613		h, _ := newTestHandler(t)
