160			{"id":"fresh","payload":{"n":1}},
161			{"id":"x","payload":{"k":2}}
162		]}`)
163		if w.Code != http.StatusConflict {
164			t.Fatalf("payload conflict status = %d body = %s", w.Code, w.Body.String())
165		}
166		if ct := w.Header().Get("Content-Type"); ct != "application/json" {
167			t.Fatalf("conflict content type = %q", ct)
168		}
169		if body["error"] == nil || body["conflictId"] != "x" {
170			t.Fatalf("conflict body = %s", w.Body.String())
171		}
172	
173		// Same id and payload but a different source device is a conflict too:
174		// only the session device AND the decoded payload matching is idempotent.
175		createSessionViaHTTP(t, h, "dev-2", "sess-2")
176		w, body = postSessionReplay(t, h, "sess-2", "doc1", `{"operations":[{"id":"x","payload":{"k":1}}]}`)
177		if w.Code != http.StatusConflict || body["conflictId"] != "x" {
178			t.Fatalf("device conflict = %d %s", w.Code, w.Body.String())
179		}
180	
181		// Both conflicts left the log untouched: no half batch, cursor unmoved.
182		rows, next, err := s.ListChanges("doc1", 0, 100)
183		if err != nil {
184			t.Fatal(err)
185		}
186		if len(rows) != 1 || rows[0].ID != "x" || next != 1 {
187			t.Fatalf("conflict leaked writes: rows = %v next = %d", rows, next)
188		}
189	}
