465		seedDoc(t, h, "doc1", 1)
466	
467		done := make(chan map[string]any, 1)
468		go func() {
469			w, body := doRequest(t, h, http.MethodGet, "/v1/documents/doc1/changes/poll?after=1&waitMs=30000")
470			if w.Code != http.StatusOK {
471				t.Errorf("poll status = %d body = %s", w.Code, w.Body.String())
472			}
473			done <- body
474		}()
475	
476		// A replay carrying a new operation wakes the parked poll.
477		time.Sleep(50 * time.Millisecond)
478		w, _ := postSessionReplay(t, h, "sess", "doc1", `{"operations":[{"id":"live","payload":{"n":2}}]}`)
479		if w.Code != http.StatusOK {
480			t.Fatal(w.Body.String())
481		}
