483		select {
484		case body := <-done:
485			rows := body["changes"].([]any)
486			if len(rows) != 1 || rows[0].(map[string]any)["id"] != "live" {
487				t.Fatalf("polled rows = %v", rows)
488			}
489			row := rows[0].(map[string]any)
490			if row["deviceId"] != "dev" || row["cursor"].(float64) != 2 {
491				t.Fatalf("polled row = %v", row)
492			}
493			if body["timedOut"] != false {
494				t.Fatalf("poll timed out despite the replay: %v", body)
495			}
496		case <-time.After(5 * time.Second):
497			t.Fatal("session replay did not wake the parked poll")
498		}
499	
500		// An idempotent replay allocates no cursor and does not wake a parked poll.
501		timed := make(chan map[string]any, 1)
502		go func() {
503			_, body := doRequest(t, h, http.MethodGet, "/v1/documents/doc1/changes/poll?after=2&waitMs=80")
504			timed <- body
505		}()
506		time.Sleep(50 * time.Millisecond)
507		w, _ = postSessionReplay(t, h, "sess", "doc1", `{"operations":[{"id":"live","payload":{"n":2.0}}]}`)
508		if w.Code != http.StatusOK {
509			t.Fatal(w.Body.String())
510		}
511		select {
512		case body := <-timed:
513			if body["timedOut"] != true || body["nextCursor"].(float64) != 2 {
514				t.Fatalf("idempotent replay woke the poll: %v", body)
515			}
516		case <-time.After(5 * time.Second):
517			t.Fatal("poll did not return")
518		}
519	}
