556	func TestSessionReplayHTTPConcurrent(t *testing.T) {
557		h, _ := newTestHandler(t)
558		createSessionViaHTTP(t, h, "dev", "sess")
559	
560		const batches, width = 20, 3
561		var wg sync.WaitGroup
562		errs := make(chan error, batches)
563		for b := 0; b < batches; b++ {
564			wg.Add(1)
565			go func(b int) {
566				defer wg.Done()
567				ops := make([]any, width)
568				for j := range ops {
569					ops[j] = map[string]any{
570						"id":      fmt.Sprintf("b%02d-o%d", b, j),
571						"payload": map[string]any{"b": b, "j": j},
572					}
573				}
574				w, _ := postSessionReplay(t, h, "sess", "doc", map[string]any{"operations": ops})
575				if w.Code != http.StatusOK {
576					errs <- fmt.Errorf("batch %d status %d: %s", b, w.Code, w.Body.String())
577				}
578			}(b)
579		}
580		wg.Wait()
581		close(errs)
582		for err := range errs {
583			t.Error(err)
584		}
585	
586		// The whole batch set took effect: every row present, cursors contiguous
587		// and never duplicated.
588		w, body := doRequest(t, h, http.MethodGet, "/v1/documents/doc/changes?limit=1000")
589		if w.Code != http.StatusOK {
590			t.Fatal(w.Body.String())
591		}
592		rows := body["changes"].([]any)
593		if len(rows) != batches*width || body["nextCursor"].(float64) != batches*width {
594			t.Fatalf("stored %d changes, nextCursor = %v, want %d", len(rows), body["nextCursor"], batches*width)
595		}
596		seenCursor := make(map[float64]bool, batches*width)
597		byBatch := make(map[string][]int64, batches)
598		for _, row := range rows {
599			r := row.(map[string]any)
600			cursor := r["cursor"].(float64)
601			if seenCursor[cursor] {
602				t.Fatalf("cursor %v allocated twice", cursor)
603			}
604			seenCursor[cursor] = true
605			byBatch[r["id"].(string)[:3]] = append(byBatch[r["id"].(string)[:3]], int64(cursor))
606		}
607		// Each individual batch committed as a whole: its width cursors are
608		// contiguous in request order, with no other batch's row interleaved.
609		for b := 0; b < batches; b++ {
610			cursors := byBatch[fmt.Sprintf("b%02d", b)]
611			if len(cursors) != width {
612				t.Fatalf("batch %d stored %d rows, want %d", b, len(cursors), width)
613			}
614			for j, cursor := range cursors {
615				if cursor != cursors[0]+int64(j) {
616					t.Fatalf("batch %d cursors not contiguous: %v", b, cursors)
617				}
618			}
619		}
620	}
