639			t.Fatal(err)
640		}
641	
642		s2, err := app.Open(path)
643		if err != nil {
644			t.Fatal(err)
645		}
646		t.Cleanup(func() { _ = s2.Close() })
647		h2 := NewHandler(s2)
648	
649		// Idempotency survives the restart: same session device and decoded
650		// payload -> created=false with the first cursor.
651		w, body := postSessionReplay(t, h2, "sess", "doc1", `{"operations":[{"id":"o1","payload":{"a":1}}]}`)
652		if w.Code != http.StatusOK {
653			t.Fatal(w.Body.String())
654		}
655		r := body["results"].([]any)[0].(map[string]any)
656		if r["created"] != false || r["cursor"].(float64) != 1 {
657			t.Fatalf("idempotent after restart = %v", r)
658		}
659	
660		// So does the conflict decision, with the whole batch rejected.
661		w, body = postSessionReplay(t, h2, "sess", "doc1", `{"operations":[
662			{"id":"fresh","payload":{"z":0}},
663			{"id":"o1","payload":{"a":2}}
664		]}`)
665		if w.Code != http.StatusConflict || body["conflictId"] != "o1" {
666			t.Fatalf("conflict after restart = %d %s", w.Code, w.Body.String())
667		}
668	
669		// Raw payloads read back verbatim and the cursor space continues.
670		w, body = doRequest(t, h2, http.MethodGet, "/v1/documents/doc1/changes")
671		if w.Code != http.StatusOK {
672			t.Fatal(w.Body.String())
673		}
674		rows := body["changes"].([]any)
675		if len(rows) != 2 || body["nextCursor"].(float64) != 2 {
676			t.Fatalf("list after restart = %v next=%v", rows, body["nextCursor"])
677		}
678		second := rows[1].(map[string]any)
679		payload := second["payload"].([]any)
680		if len(payload) != 3 || payload[0].(float64) != 1 || payload[1] != true || payload[2] != nil {
681			t.Fatalf("payload after restart = %v", second["payload"])
682		}
683	
684		w, body = postSessionReplay(t, h2, "sess", "doc1", `{"operations":[{"id":"o3","payload":42}]}`)
685		if w.Code != http.StatusOK {
686			t.Fatal(w.Body.String())
687		}
688		r = body["results"].([]any)[0].(map[string]any)
689		if r["created"] != true || r["cursor"].(float64) != 3 {
690			t.Fatalf("post-restart cursor = %v", r)
691		}
692	}
693	
694	// A compacted-away id still answers idempotency and conflict decisions from
695	// its retained summary when the replay arrives through the session path.
696	func TestSessionReplayHTTPCompactedIdentity(t *testing.T) {
697		h, _ := newTestHandler(t)
698		createSessionViaHTTP(t, h, "dev", "sess")
699		postDocChanges(t, h, "doc", "dev", 2)
700		w, _ := postJSON(t, h, "/v1/documents/doc/snapshots", map[string]any{"cursor": 2, "state": map[string]any{"s": 1}})
701		if w.Code != http.StatusOK {
702			t.Fatal(w.Body.String())
703		}
704		if w := compactChanges(t, h, "doc", "dev"); w.Code != http.StatusOK {
705			t.Fatalf("compact = %d %s", w.Code, w.Body.String())
706		}
707	
708		// The trimmed id is idempotent with its first cursor.
709		w, body := postSessionReplay(t, h, "sess", "doc", `{"operations":[{"id":"c1","payload":{"n":1}}]}`)
710		if w.Code != http.StatusOK {
711			t.Fatalf("trimmed idempotent = %d %s", w.Code, w.Body.String())
712		}
713		r := body["results"].([]any)[0].(map[string]any)
714		if r["created"] != false || r["cursor"].(float64) != 1 {
715			t.Fatalf("trimmed result = %v", r)
716		}
717	
718		// A differing payload against the trimmed id is still a 409.
719		w, body = postSessionReplay(t, h, "sess", "doc", `{"operations":[{"id":"c1","payload":{"n":9}}]}`)
720		if w.Code != http.StatusConflict || body["conflictId"] != "c1" {
721			t.Fatalf("trimmed conflict = %d %s", w.Code, w.Body.String())
722		}
723	
724		// New ids continue past the pre-compaction cursor space.
725		w, body = postSessionReplay(t, h, "sess", "doc", `{"operations":[{"id":"c3","payload":{"n":3}}]}`)
726		if w.Code != http.StatusOK {
727			t.Fatal(w.Body.String())
728		}
729		r = body["results"].([]any)[0].(map[string]any)
730		if r["created"] != true || r["cursor"].(float64) != 3 {
731			t.Fatalf("post-compaction cursor = %v", r)
732		}
733	}
734	
735	// The document-level replay is untouched by the new entry: it still requires
736	// its body deviceId and answers with its own shapes.
737	func TestSessionReplayHTTPDocumentReplayUnchanged(t *testing.T) {
738		h, _ := newTestHandler(t)
739		createSessionViaHTTP(t, h, "dev", "sess")
740	
741		w, _ := postJSON(t, h, "/v1/documents/doc1/replay", `{"operations":[{"id":"a","payload":1}]}`)
742		if w.Code != http.StatusBadRequest {
743			t.Fatalf("document replay without deviceId = %d, want 400", w.Code)
744		}
745	
746		w, body := postJSON(t, h, "/v1/documents/doc1/replay", map[string]any{
747			"deviceId":   "dev",
748			"operations": []any{map[string]any{"id": "a", "payload": 1}},
749		})
750		if w.Code != http.StatusOK {
751			t.Fatal(w.Body.String())
752		}
753		r := body["results"].([]any)[0].(map[string]any)
754		if r["created"] != true || r["cursor"].(float64) != 1 {
755			t.Fatalf("document replay result = %v", r)
756		}
757	}
758	
759	// A revoke committed while a subscription is live ends it with 4403,
760	// including when the last pushed frame arrived through the session replay;
761	// replays attempted after the revoke are a 403 and push nothing.
762	func TestSessionReplayHTTPSubscriptionRevokedCloses4403(t *testing.T) {
763		srv, _ := newWSTestServer(t)
764		setupSession(t, srv, "dev-1", "sess", "doc", 1)
765	
766		conn, resp := dialWS(t, subscribeURL(srv, "sess", "doc", "1"))
767		if conn == nil {
768			t.Fatalf("status = %d", resp.StatusCode)
769		}
770		defer conn.close()
771	
772		if code := postHTTP(t, srv, sessionReplayPath("sess", "doc"), map[string]any{
773			"operations": []any{map[string]any{"id": "replay-live", "payload": map[string]any{"n": 2}}},
774		}); code != http.StatusOK {
775			t.Fatalf("replay status = %d", code)
776		}
777		if c := conn.readChange(); c.Cursor != 2 || c.ID != "replay-live" {
778			t.Fatalf("pushed frame = %+v", c)
779		}
780	
781		if code := postHTTP(t, srv, "/v1/documents/doc/permissions", map[string]any{
782			"deviceId": "dev-1", "action": "revoke",
783		}); code != http.StatusOK {
784			t.Fatalf("revoke status = %d", code)
785		}
786		conn.setReadDeadline(2 * time.Second)
787		if code := conn.readCloseCode(); code != 4403 {
788			t.Fatalf("close code = %d, want 4403", code)
789		}
790		conn.clearReadDeadline()
791	
792		if code := postHTTP(t, srv, sessionReplayPath("sess", "doc"), map[string]any{
793			"operations": []any{map[string]any{"id": "after-revoke", "payload": map[string]any{"n": 3}}},
794		}); code != http.StatusForbidden {
795			t.Fatalf("replay after revoke = %d, want 403", code)
796		}
797		conn.setReadDeadline(300 * time.Millisecond)
798		if _, _, _, ok := conn.readFrameMaybe(); ok {
799			t.Fatal("a frame arrived after the 4403 close")
800		}
801		conn.clearReadDeadline()
802	}
803	
804	// The termination signal ends the subscription with 1001 even when its catch-up
805	// frames were produced by the session replay; committed data stays readable.
806	func TestSessionReplayHTTPSubscriptionShutdownCloses1001(t *testing.T) {
807		srv, st := newWSTestServer(t)
808		setupSession(t, srv, "dev-1", "sess", "doc", 0)
809	
810		conn, resp := dialWS(t, subscribeURL(srv, "sess", "doc", "0"))
811		if conn == nil {
812			t.Fatalf("status = %d", resp.StatusCode)
813		}
814		defer conn.close()
815	
816		if code := postHTTP(t, srv, sessionReplayPath("sess", "doc"), map[string]any{
817			"operations": []any{map[string]any{"id": "replay-1", "payload": map[string]any{"n": 1}}},
818		}); code != http.StatusOK {
819			t.Fatalf("replay status = %d", code)
820		}
821		if c := conn.readChange(); c.Cursor != 1 || c.ID != "replay-1" {
822			t.Fatalf("pushed frame = %+v", c)
823		}
824	
825		st.InterruptWaits()
826		conn.setReadDeadline(2 * time.Second)
827		if code := conn.readCloseCode(); code != 1001 {
828			t.Fatalf("close code = %d, want 1001", code)
829		}
830		conn.clearReadDeadline()
831	
832		rows, next, err := st.ListChanges("doc", 0, 100)
833		if err != nil {
834			t.Fatal(err)
835		}
836		if len(rows) != 1 || next != 1 {
837			t.Fatalf("committed state after signal = %+v/%d", rows, next)
838		}
839	}
